-- Demo data, category specific: one course per age group (7+, 8+, 9+, 10+, 11+, 13+).
-- Each course has 6 future weekly classes for that age group only, each with a material,
-- homework + answers PDFs (10 questions), and every existing child is registered into the
-- classes of their own age group. Uses the first teacher account for the classes.
-- Run ONCE in phpMyAdmin (SQL tab), after the backend has been redeployed.

CREATE TABLE IF NOT EXISTS homework_files (
  homework_id INT NOT NULL,
  kind VARCHAR(10) NOT NULL,
  data LONGBLOB NOT NULL,
  PRIMARY KEY (homework_id, kind)
);

SET @teacher := (SELECT id FROM users WHERE role = 'teacher' ORDER BY id LIMIT 1);

-- 1. One course per age group
INSERT INTO courses (name, description) VALUES ('Demo 7+ Foundation Course', 'Weekly English, maths and reasoning classes for the 7+ age group only.');
SET @c0 := LAST_INSERT_ID();
INSERT INTO courses (name, description) VALUES ('Demo 8+ Foundation Course', 'Weekly English, maths and reasoning classes for the 8+ age group only.');
SET @c1 := LAST_INSERT_ID();
INSERT INTO courses (name, description) VALUES ('Demo 9+ Foundation Course', 'Weekly English, maths and reasoning classes for the 9+ age group only.');
SET @c2 := LAST_INSERT_ID();
INSERT INTO courses (name, description) VALUES ('Demo 10+ Foundation Course', 'Weekly English, maths and reasoning classes for the 10+ age group only.');
SET @c3 := LAST_INSERT_ID();
INSERT INTO courses (name, description) VALUES ('Demo 11+ Foundation Course', 'Weekly English, maths and reasoning classes for the 11+ age group only.');
SET @c4 := LAST_INSERT_ID();
INSERT INTO courses (name, description) VALUES ('Demo 13+ Foundation Course', 'Weekly English, maths and reasoning classes for the 13+ age group only.');
SET @c5 := LAST_INSERT_ID();

-- 2. Six future classes per course
INSERT INTO classes (course_id, teacher_id, title, timing, end_timing, venue, price)
SELECT @c0, @teacher, CONCAT('7+ Class - Week ', n),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 0 DAY), '16:00:00'),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 0 DAY), '17:30:00'),
       'Room 1, Main Campus', 20.00
FROM (SELECT 1 AS n UNION ALL SELECT 2 AS n UNION ALL SELECT 3 AS n UNION ALL SELECT 4 AS n UNION ALL SELECT 5 AS n UNION ALL SELECT 6 AS n) AS t;
INSERT INTO classes (course_id, teacher_id, title, timing, end_timing, venue, price)
SELECT @c1, @teacher, CONCAT('8+ Class - Week ', n),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 1 DAY), '16:00:00'),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 1 DAY), '17:30:00'),
       'Room 2, Main Campus', 22.00
FROM (SELECT 1 AS n UNION ALL SELECT 2 AS n UNION ALL SELECT 3 AS n UNION ALL SELECT 4 AS n UNION ALL SELECT 5 AS n UNION ALL SELECT 6 AS n) AS t;
INSERT INTO classes (course_id, teacher_id, title, timing, end_timing, venue, price)
SELECT @c2, @teacher, CONCAT('9+ Class - Week ', n),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 2 DAY), '16:00:00'),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 2 DAY), '17:30:00'),
       'Room 3, Main Campus', 24.00
FROM (SELECT 1 AS n UNION ALL SELECT 2 AS n UNION ALL SELECT 3 AS n UNION ALL SELECT 4 AS n UNION ALL SELECT 5 AS n UNION ALL SELECT 6 AS n) AS t;
INSERT INTO classes (course_id, teacher_id, title, timing, end_timing, venue, price)
SELECT @c3, @teacher, CONCAT('10+ Class - Week ', n),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 3 DAY), '16:00:00'),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 3 DAY), '17:30:00'),
       'Room 4, Main Campus', 26.00
FROM (SELECT 1 AS n UNION ALL SELECT 2 AS n UNION ALL SELECT 3 AS n UNION ALL SELECT 4 AS n UNION ALL SELECT 5 AS n UNION ALL SELECT 6 AS n) AS t;
INSERT INTO classes (course_id, teacher_id, title, timing, end_timing, venue, price)
SELECT @c4, @teacher, CONCAT('11+ Class - Week ', n),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 4 DAY), '16:00:00'),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 4 DAY), '17:30:00'),
       'Room 5, Main Campus', 28.00
FROM (SELECT 1 AS n UNION ALL SELECT 2 AS n UNION ALL SELECT 3 AS n UNION ALL SELECT 4 AS n UNION ALL SELECT 5 AS n UNION ALL SELECT 6 AS n) AS t;
INSERT INTO classes (course_id, teacher_id, title, timing, end_timing, venue, price)
SELECT @c5, @teacher, CONCAT('13+ Class - Week ', n),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 5 DAY), '16:00:00'),
       TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL n * 7 + 5 DAY), '17:30:00'),
       'Room 6, Main Campus', 30.00
FROM (SELECT 1 AS n UNION ALL SELECT 2 AS n UNION ALL SELECT 3 AS n UNION ALL SELECT 4 AS n UNION ALL SELECT 5 AS n UNION ALL SELECT 6 AS n) AS t;

-- 3. Each class is for its own age group only
INSERT INTO class_categories (class_id, category)
SELECT id, CASE WHEN course_id = @c0 THEN '7+' WHEN course_id = @c1 THEN '8+' WHEN course_id = @c2 THEN '9+' WHEN course_id = @c3 THEN '10+' WHEN course_id = @c4 THEN '11+' WHEN course_id = @c5 THEN '13+' END FROM classes WHERE course_id IN (@c0, @c1, @c2, @c3, @c4, @c5);

-- 4. A material on every class (the file is created in uploads/materials when the backend starts)
INSERT INTO class_materials (class_id, file_name, file_path)
SELECT id, 'Class notes.pdf', '/uploads/materials/sample-material.pdf' FROM classes WHERE course_id IN (@c0, @c1, @c2, @c3, @c4, @c5);

-- 5. Homework + answers on every class (10 questions)
INSERT INTO homework (class_id, title, file_name, file_path, answer_file_name, answer_file_path, total_questions)
SELECT id, CONCAT(title, ' homework'), 'Homework.pdf', 'seed-homework.pdf', 'Answers.pdf', 'seed-answers.pdf', 10
FROM classes WHERE course_id IN (@c0, @c1, @c2, @c3, @c4, @c5);

INSERT INTO homework_files (homework_id, kind, data)
SELECT h.id, 'homework',  FROM homework h
JOIN classes c ON c.id = h.class_id WHERE c.course_id IN (@c0, @c1, @c2, @c3, @c4, @c5);

INSERT INTO homework_files (homework_id, kind, data)
SELECT h.id, 'answer',  FROM homework h
JOIN classes c ON c.id = h.class_id WHERE c.course_id IN (@c0, @c1, @c2, @c3, @c4, @c5);

-- 6. Register every child into the classes of their own age group
INSERT IGNORE INTO class_registrations (class_id, child_id, status)
SELECT c.id, ch.id, 'upcoming'
FROM classes c
JOIN class_categories cc ON cc.class_id = c.id
JOIN children ch ON ch.category = cc.category AND ch.parent_id IS NOT NULL
WHERE c.course_id IN (@c0, @c1, @c2, @c3, @c4, @c5);
